const CLASSROOM_NOTES={"personal":["形容词，修饰 notebook（笔记本）","This（这）+ is（是）+ my personal notebook（我的私人笔记本）。","my 后面可以接形容词再接名词：my + personal + notebook。"],"tie":["动词，表示「系」","Please（请）+ tie（系）+ the ribbon（这条丝带）。","这是祈使句；Please 后面用动词原形 tie。"],"still":["副词，表示「仍然」","She（她）+ is（在）+ still（仍然）+ at school（在学校）。","still 是副词，这句表示状态仍在持续；它不表示「静止的」。"],"offer":["动词，表示「提供」","I（我）+ can offer（能够提供）+ you（给你）+ some help（一些帮助）。","can 是情态动词，后面用动词原形 offer。offer sb. sth. = 给某人提供某物。"],"addition":["名词，固定短语 in addition","In addition（此外）+ we（我们）+ need（需要）+ water（水）。","in addition 是连接上下文的短语，表示「此外」，并不表示一道加法题。"],"success":["名词，表示「成功」","Hard work（努力）+ can lead to（能带来）+ success（成功）。","lead to 后面接名词（success）或动名词，意思是「导致；带来」。"],"produce":["动词，表示「生产；结出」","These trees（这些树）+ produce（结出）+ fruit（果实）。","trees 是复数主语，动词用原形 produce，不加第三人称单数 -s。"],"expect":["动词，表示「期待」","I（我）+ expect（期待）+ good news（好消息）。","expect 后面可以直接接名词；也常用 expect to do（期待做某事）。"],"cause":["动词过去式 caused","What（什么）+ caused（引起了）+ the problem（问题）？","cause → caused：加 -d 构成规则过去式，说明事情已经发生。"],"state":["动词，表示「说明；陈述」","Please（请）+ state（说明）+ your name（你的名字）。","state 在这里不是「国家」，而是动词；祈使句用动词原形。"],"manage":["动词，表示「管理」","She（她）+ can manage（能管理）+ the team（团队）。","情态动词 can 后使用原形 manage；manage to do 还可表示「设法做成」。"],"directly":["副词，表示「直接地」","Go（走）+ directly（直接地）+ to the library（去图书馆）。","-ly 常用于构成副词；directly 修饰动词 go，表示怎么去。"],"improve":["动词，表示「提高」","Reading（阅读）+ can improve（能够提高）+ your English（你的英语）。","Reading 是动名词作主语；can 后面用 improve 原形。"],"wonder":["动词，表示「想知道」","I（我）+ wonder（想知道）+ where he is（他在哪里）。","wonder 后面接宾语从句：where he is，而不是 where is he。"],"present":["名词，表示「礼物」","She（她）+ gave（给了）+ me（我）+ a present（一份礼物）。","present 在此是名词，不是「现在的」；gave 是 give 的过去式。"],"underline":["动词，表示「在……下划线」","Underline（划线）+ the new word（这个新单词）。","祈使句省略主语 you，直接用动词原形。"],"mislead":["动词，表示「误导」","False stories（虚假故事）+ may mislead（可能误导）+ readers（读者）。","may 后跟动词原形；mis- 是否定意义前缀，mislead 指「引向错误方向」。"],"complete":["动词，表示「完成」","Please（请）+ complete（完成）+ the task（任务）。","complete 在这里是动词；也可作形容词「完整的」，要结合句子判断。"],"lead":["动词，表示「带领」","The teacher（老师）+ will lead（将带领）+ the group（小组）。","will 后使用动词原形；lead to 另有「导致」的意思。"],"sensitive":["形容词，表示「敏感的」","Some people（一些人）+ are sensitive to（对……敏感）+ noise（噪声）。","be sensitive to + 名词，to 是介词，后面接 noise。"],"valuable":["形容词，表示「宝贵的」","Your time（你的时间）+ is（是）+ valuable（宝贵的）。","系动词 is 后可接形容词作表语；valuable 来自 value + -able。"],"courageous":["形容词，修饰 choice","The girl（这个女孩）+ made（做出）+ a courageous choice（勇敢的选择）。","形容词 courageous 放在名词 choice 前；made 是 make 的过去式。"],"tend":["动词，表示「往往；倾向」","I（我）+ tend to get up（往往起床）+ early（很早）。","tend to do sth. = 往往/倾向于做某事；to 后接动词原形。"],"matter":["动词三单 matters，表示「重要」","Your opinion（你的意见）+ matters（很重要）。","主语 opinion 是第三人称单数，因此 matter → matters。"],"realize":["动词，表示「意识到」","I（我）+ realize（意识到）+ my mistake（我的错误）。","realize 后可直接接名词或 that 引导的宾语从句。"],"acceptable":["形容词，作表语","This answer（这个答案）+ is（是）+ acceptable（可以接受的）。","accept（接受）+ -able（可……的）构成 acceptable。"],"consider":["动词，表示「考虑」","Please（请）+ consider（考虑）+ my idea（我的想法）。","consider 后面可以接名词，也常接 doing，而不是直接接 to do。"],"support":["动词第三人称单数 supports","My family（我的家人）+ supports（支持）+ me（我）。","这里 family 被当作一个整体，因此用 supports；support 也可以是名词。"],"fit":["动词第三人称单数 fits","This jacket（这件夹克）+ fits（合身）+ me（我）。","主语 jacket 是第三人称单数；fit → fits。这里不是形容词「健康的」。"],"hang":["动词，表示「悬挂」","Hang（挂上）+ your coat（你的外套）+ here（这里）。","祈使句直接用动词原形 hang。"],"protect":["动词，表示「保护」","We（我们）+ must protect（必须保护）+ the environment（环境）。","must 后用动词原形 protect；protect ... from ... 表示保护……免受……。"],"professional":["形容词，修饰 artist","She（她）+ is（是）+ a professional artist（一位专业艺术家）。","professional 可作形容词，也可作名词；这里修饰 artist。"],"widen":["动词，表示「拓宽」","They（他们）+ plan to widen（计划拓宽）+ the road（道路）。","wide（宽的）+ -en（使变得）→ widen（使变宽）。plan to do sth.。"],"require":["动词第三人称单数 requires","This job（这份工作）+ requires（需要）+ patience（耐心）。","job 是第三人称单数，因此 require → requires；后接名词 patience。"],"creative":["形容词，表示「有创意的」","He（他）+ has（有）+ a creative idea（一个有创意的想法）。","creative 修饰名词 idea；create（创造）可派生 creative。"],"deal":["动词短语 deal with","We（我们）+ can deal with（能处理）+ the problem（问题）。","deal with = 处理；can 后使用动词原形 deal。"],"popularity":["名词，表示「受欢迎」","The game（这个游戏）+ gained（获得）+ popularity（欢迎）。","gain popularity = 变得受欢迎；popular（受欢迎的）是形容词。"],"attend":["动词，表示「出席」","I（我）+ will attend（将出席）+ the meeting（会议）。","will 后跟动词原形 attend；attend 表示出席，不需加 to。"],"prefer":["动词，表示「更喜欢」","I（我）+ prefer（更喜欢）+ tea to coffee（茶胜过咖啡）。","prefer A to B = 比起B更喜欢A。"],"wild":["形容词，修饰 animals","Wild animals（野生动物）+ live（生活）+ here（这里）。","wild 修饰复数名词 animals；复数主语后用 live 原形。"],"quality":["名词，表示「质量」","The quality of the book（书的质量）+ is（是）+ good（好的）。","句子主语中心词是 quality（单数），所以使用 is。"],"perform":["动词，表示「表演」","The children（孩子们）+ perform（表演）+ on stage（在舞台上）。","children 是复数名词，谓语用 perform 原形。"],"promise":["动词，表示「承诺」","I（我）+ promise to help（答应帮助）+ you（你）。","promise to do sth. = 答应做某事；promise 也可以是名词。"],"necessarily":["副词，表示「必然地」","Expensive（昂贵）+ does not necessarily mean（未必意味着）+ better（更好）。","not necessarily = 不一定；necessarily 修饰动词 mean。"],"store":["动词，表示「储存」","We（我们）+ store（存放）+ books（书）+ in this room（在这个房间）。","store 在这里是动词「储存」；作名词还可表示「商店」。"],"general":["形容词，表示「普遍的」","This（这）+ is（是）+ a general rule（一条普遍的规则）。","general 修饰名词 rule。"],"condition":["名词，表示「状况」","The road（这条路）+ is（处于）+ in good condition（良好状态）。","in good condition = 状况良好；condition 在这里是名词。"],"vary":["动词，表示「变化」","The weather（天气）+ can vary（可能变化）+ a lot（很大）。","can 后用 vary 原形；various 是相关形容词「各种各样的」。"],"suffer":["动词，表示「遭受」","Many people（许多人）+ suffer from（遭受）+ stress（压力）。","suffer from + 病痛/问题/压力等，是高频搭配。"],"speech":["名词，表示「演讲」","Her speech（她的演讲）+ was（是）+ short（简短的）。","speech 是可数名词；was 是 be 的过去式。"],"respect":["动词，表示「尊重」","We（我们）+ should respect（应该尊重）+ others（其他人）。","should 后接动词原形 respect；respect 也能作名词。"],"disappoint":["动词，表示「使失望」","I（我）+ do not want（不想）+ to disappoint you（让你失望）。","want to do sth. = 想做某事；disappointed 表示「感到失望的」。"],"simplify":["动词，表示「简化」","This chart（这张图表）+ can simplify（能简化）+ the lesson（课程）。","simple（简单的）→ simplify（使简化）；can 后用原形。"],"raise":["动词，表示「举起」","Please（请）+ raise（举起）+ your hand（手）。","raise 是及物动词，后面接宾语；与 rise（升起）区分。"],"refer":["动词短语 refer to","Refer to（查阅）+ the map（地图）。","refer to = 查阅、提及；祈使句直接用原形 refer。"],"achievement":["名词，表示「成就」","This（这）+ is（是）+ a great achievement（一项伟大的成就）。","achieve（实现）→ achievement（成就），-ment 常构成名词。"],"particular":["形容词，表示「特定的」","I（我）+ like（喜欢）+ this particular book（这一本特别的书）。","particular 修饰 book；in particular = 尤其。"],"prevent":["动词，表示「防止」","A hat（帽子）+ can help prevent（有助于预防）+ sunburn（晒伤）。","prevent sb. from doing sth. = 阻止某人做某事。"],"regular":["形容词，表示「有规律的」","She（她）+ has（有）+ a regular study plan（有规律的学习计划）。","regular 修饰 study plan；regularly 是副词，表示「定期地」。"],"connect":["动词，表示「连接」","Connect（联系起来）+ the two ideas（这两个想法）。","connect A with/to B = 把A和B联系起来；这里是祈使句。"]};
const WORD_BUILD={"personal":"person（人）+ -al（形容词后缀）→ personal（个人的）","addition":"add（加；增加）→ addition（增加；加法）。这是名词派生，不是时态变化。","directly":"direct（直接的）+ -ly（副词后缀）→ directly（直接地）","valuable":"value（价值）+ -able（可……的）→ valuable（有价值的）","acceptable":"accept（接受）+ -able（可……的）→ acceptable（可接受的）","professional":"profession（职业；专业）→ professional（专业的）","widen":"wide（宽的）+ -en（使变得）→ widen（拓宽）","creative":"create（创造）→ creative（有创意的）","popularity":"popular（受欢迎的）+ -ity（名词后缀）→ popularity（受欢迎；流行）","necessarily":"necessary（必要的）→ necessarily（必然地）","simplify":"simple（简单的）→ simplify（简化）","achievement":"achieve（实现）+ -ment（名词后缀）→ achievement（成就）","carefully":"care（关心）+ -ful + -ly → carefully（小心地）","mislead":"mis-（错误地）+ lead（引导）→ mislead（误导）"};
