const READING_INFLECTIONS={"offers":["offer","主语为第三人称单数时，一般现在时的动词通常加 -s：offer → offers。在这篇文章中，主语是 Mia。"],"has":["have","have → has：第三人称单数使用 has。Mia has a notebook = 米娅有一本笔记本。"],"uses":["use","use → uses：主语 she 是第三人称单数，动词在一般现在时加 -s。"],"says":["say","say → says：一般现在时第三人称单数形式，读音和拼写需要一起记。"],"asks":["ask","ask → asks：主语 teacher 是第三人称单数，加 -s。"],"needs":["need","need → needs：第三人称单数形式；some plants need（复数主语则不加 -s）。"],"wants":["want","want → wants：主语 Lily 是第三人称单数，加 -s。"],"makes":["make","make → makes：以 e 结尾的动词一般直接加 -s。"],"gets":["get","get → gets：第三人称单数形式。"],"believes":["believe","believe → believes：第三人称单数形式。"],"becomes":["become","become → becomes：第三人称单数形式。"],"works":["work","work → works：第三人称单数加 -s；注意句中主语是否单数。"],"friends":["friend","friend → friends：可数名词复数通常加 -s，这不是动词三单。"],"students":["student","student → students：可数名词复数加 -s。"],"plants":["plant","plant → plants：可数名词复数加 -s。"],"books":["book","book → books：名词复数加 -s。"],"opinions":["opinion","opinion → opinions：名词复数加 -s。"],"activities":["activity","activity → activities：辅音字母 + y 结尾，复数时 y → ies。"],"was":["be","was 是 be 动词的一般过去式，常与单数主语连用。"],"are":["be","are 是 be 动词现在时形式，常与复数主语、you 连用。"],"is":["be","is 是 be 动词现在时形式，常与第三人称单数主语连用。"]};
const READING_TRANSLATIONS={"A Little Help":["米娅有一本私人笔记本。","她每天仍然使用它。","当朋友遇到问题时，米娅主动提出帮忙。","他们一起努力改进计划。","老师说，小小的行动也能带来成功。"],"A Better School Garden":["学生们想保护学校的花园。","一些植物需要更多的水。","老师让大家考虑一个简单的解决办法。","他们决定每天早上检查植物。","这个小小的变化能够改善花园的状况。"],"The Library Project":["莉莉想组织一场阅读活动。","起初，她担心费用。","朋友们主动表示支持这个项目。","他们发布一份小通知并收集旧书。","很快，更多学生来到图书馆。"],"A Chance to Learn":["汤姆得到了参加科学社团的机会。","他很紧张，因为这门学科对他来说是新的。","老师提醒他练习很重要。","汤姆制定了有规律的计划，并努力一次专注一件事。","渐渐地，他变得更加自信。"],"The Volunteer Team":["一群志愿者决定帮助他们的社区。","他们最关注的是缺少干净的公共空间。","他们安排了一项周末活动，并与当地居民交流。","这个项目没有解决所有问题，但产生了积极的影响。"],"A New Idea":["妮娜为班级想出了一个有创意的点子。","她想联系不同学校的学生。","她的计划需要仔细准备，但她相信它很有价值。","她做了一个简短演讲来解释这个项目，并请其他人分享看法。"]};
function posOf(i){return WORD_POS[i]||'词性待核对'}
function topicGrammar(i){return CLASSROOM_NOTES[WORDS[i].en.trim().toLowerCase()]||null}
function posMini(i){return `<div class="pos-chip">${escapeWord(posOf(i))}</div>`}
function studyDetailMarkup(i) {
 const key=WORDS[i].en.trim().toLowerCase(), example=STUDY_EXAMPLES[key], notes=topicGrammar(i);
 if(!example)return WORD_BUILD[key]?`<p class="lesson-tip">构词提示：${escapeWord(WORD_BUILD[key])}</p>`:'';
 const expanded=Boolean(data.journey.showGrammar);
 return `<div class="lesson-card">
   <div class="flow-lesson-row">
     <div><div class="example-en">${escapeWord(example[0])}</div><div class="example-cn">${escapeWord(example[1])}</div></div>
     <button type="button" class="btn flow-audio" aria-label="朗读例句" onclick="speak(STUDY_EXAMPLES[WORDS[data.journey.id].en.trim().toLowerCase()][0])">♫</button>
   </div>
   <button type="button" class="btn ghost grammar-toggle" aria-expanded="${expanded}" aria-controls="flow-grammar" onclick="toggleClassroomGrammar()">${expanded?'收起语法 ↑':'展开语法 ↓'}</button>
   <div id="flow-grammar"${expanded?'':' hidden'}>${expanded?`<div class="grammar-extra">
     <p>${escapeWord(notes?notes[1]:'先找出谁做什么，再看目标单词在句子里的作用。')}</p>
     ${notes?`<p>本句中：${escapeWord(notes[0])}</p>`:''}
     <p>${escapeWord(notes?notes[2]:'这个词的详细句法说明仍在补充。')}</p>
     ${WORD_BUILD[key]?`<p>构词提示：${escapeWord(WORD_BUILD[key])}</p>`:''}
     <p class="fineprint">词形变化（如 offer → offers）和构词派生（如 person → personal）是不同知识点。</p>
   </div>`:''}</div>
 </div>`;
}
function toggleClassroomGrammar(){
 const j=data.journey;
 if(!j||!['teach','copy'].includes(j.phase))return;
 j.showGrammar=!j.showGrammar;
 renderFlowCopy();
 document.querySelector('.flow-lesson .grammar-toggle')?.focus({preventScroll:true});
}
function normalizeReadTerm(k){return String(k||'').toLowerCase().replace(/[^a-z]/g,'')}
function inferReadingTerm(raw){
 const k=normalizeReadTerm(raw),found=readKeyForWord(k);
 if(found>=0)return {cn:WORDS[found].cn,pos:posOf(found),base:WORDS[found].en.trim(),morph:'',core:true};
 if(READING_WORD_INFO[k])return {cn:READING_WORD_INFO[k][1],pos:READING_WORD_INFO[k][0],base:(READING_INFLECTIONS[k]||[])[0]||k,morph:(READING_INFLECTIONS[k]||[])[1]||'',core:readKeyForWord((READING_INFLECTIONS[k]||[])[0]||k)>=0};
 const tries=[];
 if(k.endsWith('ies'))tries.push(k.slice(0,-3)+'y');
 if(k.endsWith('es'))tries.push(k.slice(0,-2),k.slice(0,-1));
 if(k.endsWith('s')&&!k.endsWith('ss'))tries.push(k.slice(0,-1));
 if(k.endsWith('ing'))tries.push(k.slice(0,-3),k.slice(0,-3)+'e');
 if(k.endsWith('ed'))tries.push(k.slice(0,-2),k.slice(0,-1));
 for(const b of tries){const i=readKeyForWord(b);if(i>=0)return {cn:WORDS[i].cn+'（可能是词形变化）',pos:posOf(i),base:WORDS[i].en.trim(),morph:'该形式可能由 '+b+' 变化而来，具体用法需要结合句子确认。',core:true};if(READING_WORD_INFO[b])return {cn:READING_WORD_INFO[b][1]+'（可能是词形变化）',pos:READING_WORD_INFO[b][0],base:b,morph:'结合上下文判断它是复数、时态还是其他变化。',core:false}}
 return {cn:(typeof READER_DICT!=='undefined'&&READER_DICT[k])||'释义待补充',pos:'词性待补充',base:k,morph:'这不是完整识别结果，网站不会猜测词性或词形来源。',core:false};
}
function escapeInputTerm(k){return escapeWord(normalizeReadTerm(k))}
function sentenceLines(txt){return String(txt).match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[]}
function readSentenceWords(txt){return (txt.match(/[A-Za-z]+(?:'[A-Za-z]+)?|[^A-Za-z]+/g)||[]).map(v=>/^[A-Za-z]/.test(v)?`<button class="read-word ${(data.readLookups||{})[lookupKey(v)]?'seen':''}" onclick="tapReadingWord('${lookupKey(v)}')">${escapeWord(v)}</button>`:escapeWord(v)).join('')}
function changeTranslationMode(mode){if(!['none','sentence','all'].includes(mode))return;data.translationView=mode;save();renderStory()}
function toggleSentenceTranslation(i){data.visibleSentences=data.visibleSentences||{};const key=String(readingCurrent)+':'+i;data.visibleSentences[key]=!data.visibleSentences[key];save();renderStory()}

let flowTimer=null;
function flowSoon(fn,ms=1000){if(flowTimer)clearTimeout(flowTimer);flowTimer=setTimeout(()=>{flowTimer=null;if(tab==='study'&&data.journey&&data.journey.active)fn()},ms)}
function flowTop(){try{window.scrollTo({top:0,behavior:'smooth'})}catch(e){window.scrollTo(0,0)}}
function spellWord(id){return WORDS[id].en.trim().toLowerCase().replace(/[^a-z]/g,'')}
function escapeWord(s){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}
function tilesFor(id){return shuffle([...spellWord(id)])}
function nextUnlearned(){return WORDS.findIndex((w,i)=>!Object.prototype.hasOwnProperty.call(data.learned,i))}
function introProgress(){const j=data.journey;return `<div class="row"><span class="progress-text">🌸 本轮新词 ${j.newDone}/${j.target}</span><span class="tag">🧠 待抽查 ${j.pending.length}</span></div><div class="bar"><div class="fill" style="width:${Math.max(3,Math.min(100,j.target?j.newDone*100/j.target:100))}%"></div></div>`}
function startJourney(){tab='study';if(flowTimer)clearTimeout(flowTimer);let j=data.journey;if(!j||!j.active||j.date!==day()){
 const target=Math.max(0,Math.min(WORDS.length-learned(),data.daily-fresh()));
 const prior=shuffle(Object.keys(data.learned).filter(id=>data.learned[id].date===day()).map(Number)).slice(0,4);
 const old=shuffle(due()).filter(id=>!prior.includes(id)).slice(0,3);
 j={active:true,date:day(),target,newDone:0,tick:0,pending:[...prior,...old].map((id,i)=>({id,at:2+i,attempts:0})),phase:'init',id:null,question:null,copies:0,checks:0};data.journey=j;
}
 save();if(j.phase==='teach')renderFlowTeach();else if(j.phase==='copy')renderFlowCopy();else if(j.phase==='quiz')renderFlowQuiz();else flowNext();flowTop()}
function flowNext(){if(flowTimer)clearTimeout(flowTimer);const j=data.journey;if(!j||!j.active){study();return}
 j.question=null;j.id=null;
 const ready=j.pending.filter(p=>p.at<=j.tick);
 if(ready.length&&!(j.lastKind==='quiz'&&j.newDone<j.target)){const chosen=shuffle(ready)[0];j.pending.splice(j.pending.indexOf(chosen),1);beginFlowQuiz(chosen);return}
 if(j.newDone<j.target){const id=nextUnlearned();if(id>=0){j.id=id;j.phase='teach';save();renderFlowTeach();flowTop();return}j.newDone=j.target}
 if(j.pending.length){const chosen=shuffle(j.pending)[0];j.pending.splice(j.pending.indexOf(chosen),1);beginFlowQuiz(chosen);return}
 j.active=false;j.phase='done';save();$('app').innerHTML=`<div class="card"><div class="hero"><div style="font-size:60px">🏆🌸</div><h2>今天的连续学习完成啦！</h2><p>本轮认识 <b>${j.newDone}</b> 个新词，完成 <b>${j.checks}</b> 次穿插抽查。</p><p class="muted">你可以去樱花小镇自由探索，或者随时回来复习。</p></div><button class="btn primary wide" onclick="navigate('map')">🏝️ 前往樱花小镇</button><button class="btn wide" onclick="navigate('study')">📚 返回学习页面</button></div>`;refresh();flowTop()}
function renderFlowTeach(){
 renderFlowCopy();
}
function beginFlowCopy(){
 const j=data.journey;
 if(j.phase!=='teach')return;
 Object.assign(j,{phase:'copy',tiles:tilesFor(j.id),picked:[],typed:'',writeMode:j.writeMode||data.copyPreference||'tiles',feedback:''});
 renderFlowCopy();
}
function flowSetMode(mode){const j=data.journey;if(!['tiles','keyboard'].includes(mode))return;j.writeMode=mode;data.copyPreference=mode;j.picked=[];j.typed='';j.feedback='';save();renderFlowCopy()}
function chosenWord(){const j=data.journey;return (j.picked||[]).map(i=>j.tiles[i]).join('')}
function drawTiles(){const j=data.journey,word=spellWord(j.id);return `<div class="slots">${[...word].map((c,i)=>`<div class="slot">${escapeWord(chosenWord()[i]||'·')}</div>`).join('')}</div><div class="letter-bank">${j.tiles.map((c,i)=>`<button class="letter-tile" onclick="flowPick(${i})" ${j.picked.includes(i)?'disabled':''}>${escapeWord(c)}</button>`).join('')}</div><div class="grid"><button class="btn smallbtn" onclick="flowUndo()">↩️ 撤回</button><button class="btn smallbtn" onclick="flowReset()">🔄 重排</button></div>`}
function typingGuideMarkup(value='',reveal=true){const word=spellWord(data.journey.id),v=String(value||'').toLowerCase();return `<div class="typing-display">${[...word].map((ch,i)=>{const filled=i<v.length;const status=filled?(v[i]===ch?'ok':'no'):(i===v.length?'next':'');return `<span class="typing-letter ${status}" aria-label="字母${i+1}">${filled?escapeWord(v[i]):(reveal?'·':'_')}</span>`}).join('')}</div>`}
function flowPick(i){const j=data.journey;if(!j||!['copy','quiz'].includes(j.phase)||j.writeMode!=='tiles'||j.picked.includes(i))return;j.picked.push(i);if(j.phase==='copy')renderFlowCopy();else renderFlowQuiz();if(j.picked.length===spellWord(j.id).length)flowCheckSpelling(chosenWord())}
function flowUndo(){const j=data.journey;j.picked.pop();if(j.phase==='copy')renderFlowCopy();else renderFlowQuiz()}
function flowReset(){const j=data.journey;j.picked=[];j.tiles=tilesFor(j.id);if(j.phase==='copy')renderFlowCopy();else renderFlowQuiz()}
function flowTypingInput(el){const j=data.journey;if(!j||!['copy','quiz'].includes(j.phase))return;const target=spellWord(j.id);const val=el.value.toLowerCase().replace(/[^a-z]/g,'').slice(0,target.length);if(el.value!==val)el.value=val;j.typed=val;const g=$('typing-guide');if(g)g.innerHTML=typingGuideMarkup(val,j.phase==='copy');const st=$('typing-status');if(st){const correctPrefix=[...val].filter((c,i)=>c===target[i]).length;st.textContent=val===target?'🎉 全部字母正确！自动继续……':val.length===target.length?'有字母顺序不对，请修改红色字母。':`已打 ${val.length}/${target.length} 个字母 · 正确位置 ${correctPrefix} 个`;}save();if(val===target){el.disabled=true;flowCheckSpelling(val)}}
function flowCheckKeyboard(){const x=$('wordInput');if(!x)return;const typed=x.value.toLowerCase().replace(/[^a-z]/g,'');if(typed.length<spellWord(data.journey.id).length){const st=$('typing-status');if(st)st.textContent='还没打完，继续输入就好～';return}flowCheckSpelling(typed)}
function flowCheckSpelling(typed){const j=data.journey;if(!j||!['copy','quiz'].includes(j.phase))return;const correct=typed===spellWord(j.id);if(j.phase==='quiz'){flowReviewResult(correct);return}
 if(correct){j.phase='transition';if(!data.learned[j.id]){data.learned[j.id]={date:day(),due:later(1),stage:0,last:day(),errors:0};j.newDone++;}
 j.copies++;j.tick++;j.lastKind='copy';data.stars+=1;j.pending.push({id:j.id,at:j.tick+2+Math.floor(Math.random()*3),attempts:0});save();$('app').innerHTML=`<div class="card">${introProgress()}<div class="feedback">🎉 跟写正确！<br><b>${escapeWord(WORDS[j.id].en.trim())}</b> 已加入今日学习。<p class="muted">自动前往下一步……</p></div><button class="btn primary wide" onclick="flowNext()">立即继续 ➜</button></div>`;refresh();flowSoon(flowNext,1050)}
 else{data.difficult[j.id]=(data.difficult[j.id]||0)+1;j.feedback=`<div class="feedback bad">顺序还不对，看看上面的英文，再拼一次就好。</div>`;j.picked=[];j.typed='';j.tiles=tilesFor(j.id);save();renderFlowCopy()}}
function flowReveal(){const j=data.journey;if(!j)return;const id=j.id;const label=WORDS[id].en.trim();if(j.phase==='copy'){if(!data.learned[id]){data.learned[id]={date:day(),due:later(1),stage:0,last:day(),errors:1};j.newDone++;}data.difficult[id]=(data.difficult[id]||0)+1;j.pending.push({id,at:j.tick+2,attempts:1});j.tick++;j.lastKind='copy';j.phase='transition';save();$('app').innerHTML=`<div class="card"><div class="feedback-purple">💡 正确单词是 <b>${escapeWord(label)}</b>。<p class="muted">已经安排稍后再练。不会也能继续学习。</p></div><button class="btn primary wide" onclick="flowNext()">继续学习 ➜</button></div>`;refresh();flowSoon(flowNext,1250)}else if(j.phase==='quiz'){flowReviewResult(false,true)}}
function beginFlowQuiz(p){const j=data.journey,id=p.id,type=['enZh','zhEn','spell'][Math.floor(Math.random()*3)];j.id=id;j.phase='quiz';j.question={type,attempts:p.attempts||0,options:shuffle([id,...shuffle(WORDS.map((_,i)=>i).filter(i=>i!==id)).slice(0,3)])};j.tiles=tilesFor(id);j.picked=[];j.writeMode=data.copyPreference||'tiles';j.typed='';j.hint=false;save();renderFlowQuiz();flowTop()}
function renderFlowQuiz(){const j=data.journey,q=j.question,id=j.id,w=WORDS[id];if(q.type==='spell'){renderFlowCopy();return}const enZh=q.type==='enZh';$('app').innerHTML=`<div class="card">${introProgress()}<div class="row"><b>🦉 课堂突然抽查</b><span class="tag">${enZh?'英译汉':'汉译英'}</span></div><div class="journey-card"><p class="muted">前面学过的单词，试试看还记得吗？</p><div class="journey-word" style="font-size:${enZh?32:24}px">${escapeWord(enZh?w.en.trim():w.cn)}</div>${enZh?`<button class="btn green wide" onclick="speak(WORDS[data.journey.id].en)">🔊 听英语发音</button>`:''}</div>${q.options.map(i=>`<button class="btn option" onclick="flowAnswer(${i})">${escapeWord(enZh?WORDS[i].cn.split('；')[0]:WORDS[i].en.trim())}</button>`).join('')}<button class="btn wide" onclick="flowHint()">💡 提示：音标</button><div id="flow-hint">${j.hint?escapeWord(w.ipa||'本词音标待核对，可听发音'):''}</div><p class="flow-caption">答题后会自动回到新词学习，错词会隔开重练。</p></div>`;refresh()}
function flowHint(){const j=data.journey;j.hint=true;save();const h=$('flow-hint');if(h)h.innerHTML=`<div class="soft">${escapeWord(WORDS[j.id].ipa||'此词音标待核对，请听发音')}</div>`}
function flowAnswer(id){const j=data.journey;if(!j||j.phase!=='quiz')return;flowReviewResult(id===j.id)}
function flowReviewResult(correct,revealed=false){const j=data.journey;if(!j||j.phase!=='quiz')return;const id=j.id,w=WORDS[id],q=j.question,rec=data.learned[id]||{date:day(),stage:0,errors:0};rec.last=day();j.tick++;j.checks++;j.lastKind='quiz';
 if(correct&&!revealed){rec.stage=Math.min(5,(rec.stage||0)+1);rec.due=later([1,2,4,7,15,30][rec.stage]);data.steps++;data.stars+=j.hint?1:3;data.quizCount++;if(data.quizCount%3===0)data.dice++;if(data.difficult[id])data.difficult[id]=Math.max(0,data.difficult[id]-1);if(!data.difficult[id])delete data.difficult[id];}
 else{rec.errors=(rec.errors||0)+1;rec.stage=0;rec.due=later(1);data.difficult[id]=(data.difficult[id]||0)+1;if(q.attempts<2)j.pending.push({id,at:j.tick+2+Math.floor(Math.random()*2),attempts:q.attempts+1})}
 data.learned[id]=rec;j.phase='transition';save();$('app').innerHTML=`<div class="card">${introProgress()}<div class="feedback ${correct&&!revealed?'':'bad'}"><b>${correct&&!revealed?'🎉 答对啦！+1步，获得星星':'🌱 没关系，已加入隔题重练'}</b><p><b>${escapeWord(w.en.trim())}</b>：${escapeWord(w.cn)}</p><p class="muted">下一张学习卡自动出现……</p></div><button class="btn primary wide" onclick="flowNext()">立即继续 ➜</button></div>`;refresh();flowSoon(flowNext,1400)}

