function readingSentenceFor(k,preferStory){
 const search=normalizeReadTerm(k),order=[...READ_STORIES.keys()];if(Number.isInteger(preferStory)&&preferStory>=0&&preferStory<READ_STORIES.length){order.splice(order.indexOf(preferStory),1);order.unshift(preferStory)}
 for(const si of order){const sentences=sentenceLines(READ_STORIES[si].text);for(let n=0;n<sentences.length;n++){if((sentences[n].toLowerCase().match(/[a-z]+/g)||[]).includes(search)){return {story:si,index:n,en:sentences[n].trim(),cn:(READING_TRANSLATIONS[READ_STORIES[si].title]||[])[n]||'本句中文待补充'}}}}
 return null;
}
function meaningForLookup(k){
 const word=normalizeReadTerm(k),known=READING_EXACT_FORMS[word];if(known)return {base:known[0],pos:known[1],cn:known[2],grammar:known[3],morph:known[3],core:readKeyForWord(word)>=0||readKeyForWord(known[0])>=0};
 const inInfo=READING_WORD_INFO[word];const core=readKeyForWord(word);
 if(inInfo)return {base:word,pos:inInfo[0],cn:inInfo[1],grammar:READING_USAGE[word]||'此处按词在原句中的词性理解；没有额外的词形变化。',morph:'',core:core>=0};
 if(core>=0){const w=WORDS[core];return {base:word,pos:posOf(core),cn:w.cn,grammar:WORD_BUILD[word]||READING_USAGE[word]||'这是词条本身的形式；结合原句理解它在句中的作用。',morph:'',core:true}}
 const old=READING_INFLECTIONS[word];if(old){const base=old[0],id=readKeyForWord(base),meta=READING_WORD_INFO[base];return {base,pos:id>=0?posOf(id):(meta?meta[0]:'词性待补充'),cn:id>=0?WORDS[id].cn:(meta?meta[1]:'释义待补充'),grammar:old[1],morph:old[1],core:id>=0}}
 // Do not infer grammatical roles solely by stripping -s, -ed, -ing.
 const translated=READER_DICT[word];return {base:word,pos:'词性待补充',cn:translated||'释义待补充',grammar:'暂未收录这个词的句中语法说明，不能只凭结尾猜测词形。',morph:'',core:false};
}
function readingWordGrammar(k,context){
 const info=meaningForLookup(k);let grammar=info.grammar;
 if(k==='her'&&context&&/\breminds\s+her\b/i.test(context.en))grammar='这里 her 是宾格代词，reminds her 表示「提醒她」；不同于 her friend 中的 her（她的）。';
 if(k==='to'&&context&&/\bto\s+(help|focus|improve|protect|learn|support|attend|check|organize|connect|explain|share|consider)\b/i.test(context.en))grammar='to + 动词原形构成不定式；例如 to help 表示「去帮助」。';
 if(k==='more'&&context&&/more\s+confident/i.test(context.en))grammar='more + 形容词构成比较级；more confident 表示「更加自信」。';
 return grammar;
}
function readSentenceWords(txt,sentIx){return (txt.match(/[A-Za-z]+(?:'[A-Za-z]+)?|[^A-Za-z]+/g)||[]).map(v=>/^[A-Za-z]/.test(v)?`<button class="read-word ${(data.readLookups||{})[lookupKey(v)]?'seen':''}" onclick="tapReadingWord('${lookupKey(v)}',${sentIx})">${escapeWord(v)}</button>`:escapeWord(v)).join('')}
let readingCardKey=null,readingCardSentence=null,readingCardReveal=false;
function readingWordPanel(k,context,reveal){
 const info=meaningForLookup(k),record=(data.readLookups||{})[k]||{},lookCtx=context||readingSentenceFor(k,readingCurrent),grammar=readingWordGrammar(k,lookCtx);
 const txt=lookCtx?`<div class="read-context"><strong>📖 点击时所在原句</strong><div class="en">${escapeWord(lookCtx.en)}</div><div class="review-sub">出自《${escapeWord(READ_STORIES[lookCtx.story].title)}》</div><button class="translation-reveal" onclick="toggleReadingCardTranslation()">${reveal?'隐藏这句中文 ↑':'查看这句中文 ↓'}</button>${reveal?`<div class="sentence-translation">${escapeWord(lookCtx.cn)}</div>`:''}</div>`:'';
 return `<div class="row"><div><div class="kicker">WORD DETAIL · 句中解释</div><b class="lookup-word">${escapeWord(k)}</b><div class="fineprint">${escapeWord(info.pos)} · 已查询 ${Number(record.count)||0} 次</div></div><button class="btn smallbtn" onclick="speak('${escapeInputTerm(k)}')">♫ 发音</button></div><div class="lookup-cn">${escapeWord(info.cn)}</div>${info.base!==k?`<div class="lesson-tip"><b>原形：</b>${escapeWord(info.base)}</div>`:''}<div class="lesson-tip"><b>🧩 为什么这样写？</b><p>${escapeWord(grammar)}</p></div>${txt}<button class="btn smallbtn" onclick="startReadReview('mixed','${escapeInputTerm(k)}')">🧠 复习这个词与句子 →</button><p class="fineprint">${info.core?'属于688核心词或其变形。':'阅读扩展词，不计入688词掌握量。'}查询只记入生词本，不算答错。</p>`;
}
function tapReadingWord(k,sentIx){
 const word=normalizeReadTerm(k),st=READ_STORIES[readingCurrent],sentences=sentenceLines(st.text),idx=Number.isInteger(sentIx)?sentIx:sentences.findIndex(x=>(x.toLowerCase().match(/[a-z]+/g)||[]).includes(word));
 const context=idx>=0?{story:readingCurrent,index:idx,en:sentences[idx].trim(),cn:(READING_TRANSLATIONS[st.title]||[])[idx]||'本句中文待补充'}:readingSentenceFor(word,readingCurrent),info=meaningForLookup(word);
 data.readLookups=data.readLookups||{};const rec=data.readLookups[word]||{count:0,first:day()};rec.count++;rec.last=day();rec.cn=info.cn;rec.pos=info.pos;rec.base=info.base;
 if(context){rec.story=context.story;rec.sentenceIndex=context.index;rec.sourceSentence=context.en;rec.sourceCn=context.cn}data.readLookups[word]=rec;save();
 readingCardKey=word;readingCardSentence=context;readingCardReveal=false;const panel=$('lookup-panel');if(panel){panel.innerHTML=readingWordPanel(word,context,false)}
 document.querySelectorAll('.read-word').forEach(x=>x.classList.toggle('current-word',x.textContent.toLowerCase()===word));
}
function toggleReadingCardTranslation(){if(!readingCardKey)return;readingCardReveal=!readingCardReveal;const panel=$('lookup-panel');if(panel)panel.innerHTML=readingWordPanel(readingCardKey,readingCardSentence,readingCardReveal)}
function showLookupCard(k){const rec=(data.readLookups||{})[k];if(!rec)return;const context=rec.sourceSentence?{story:Number.isInteger(rec.story)?rec.story:0,index:rec.sentenceIndex||0,en:rec.sourceSentence,cn:rec.sourceCn||'本句中文待补充'}:readingSentenceFor(k);
 readingCardKey=k;readingCardSentence=context;readingCardReveal=false;
 $('app').innerHTML=`<div class="card"><button class="btn smallbtn" onclick="navigate('reader')">← 阅读生词本</button><div class="lookup-panel" id="lookup-panel">${readingWordPanel(k,context,false)}</div></div>`;refresh();
}
// Each word is reviewed in up to three stages: word meaning, original sentence, curated new sentence.
let readReviewSession=null;
function readRecallRecord(k){data.readRecall=data.readRecall||{};return data.readRecall[k]||(data.readRecall[k]={seen:0,correct:0,wrong:0,stage:0,due:day()})}
function readReviewCandidates(){return Object.keys(data.readLookups||{}).filter(k=>data.readLookups[k]&&data.readLookups[k].count>0)}
function makeReadingQuizItem(k,mode){
 const info=meaningForLookup(k),rec=(data.readLookups||{})[k]||{},orig=rec.sourceSentence?{story:typeof rec.story==='number'?rec.story:0,index:rec.sentenceIndex||0,en:rec.sourceSentence,cn:rec.sourceCn||'本句中文待补充'}:readingSentenceFor(k),fresh=READING_NEW_SENTENCES[k]||READING_NEW_SENTENCES[info.base];
 if(mode==='fresh'&&!fresh)return null;
 if(mode==='original'&&!orig)return null;
 const allWords=readReviewCandidates().filter(x=>x!==k).map(w=>meaningForLookup(w).cn).filter(x=>x&&!/待补充/.test(x));
 const allSentences=READ_STORIES.flatMap(st=>(READING_TRANSLATIONS[st.title]||[])).filter(x=>x&&x!==orig?.cn&&x!==fresh?.[1]);
 const correct=mode==='word'?info.cn:mode==='original'?orig.cn:fresh[1];
 const fallback=['帮助别人','在花园里种花','每天早起读书','这件事很重要','他们今天去上学','学生们一起练习','他正在学习英语','她给朋友写信'];
 let distractors=(mode==='word'?allWords:allSentences).concat(fallback).filter(x=>x!==correct);
 distractors=[...new Set(distractors)].sort(()=>Math.random()-.5).slice(0,3);
 let opts=shuffle([correct,...distractors]);
 return {word:k,mode,correct,opts,prompt:mode==='word'?k:mode==='original'?orig.en:fresh[0],context:orig,grammar:readingWordGrammar(k,orig),base:info.base};
}
function startReadReview(mode,k=null){
 let keys=k?[normalizeReadTerm(k)]:readReviewCandidates();if(!keys.length){alert('阅读生词本还没有记录。先到书屋点词吧。');return}
 const items=[];keys=shuffle(keys);
 for(const key of keys){let modes=mode==='mixed'?['word','original','fresh']:[mode];for(const m of modes){const q=makeReadingQuizItem(key,m);if(q)items.push(q)}}
 if(!items.length){alert('当前生词还没有可用的新句练习；请先尝试词义或原句复习。');return}
 readReviewSession={items,idx:0,correct:0,wrong:0,choice:null};drawReadReview();
}
function drawReadReview(){
 const s=readReviewSession;if(!s)return;
 if(s.idx>=s.items.length){const count=s.items.length;$('app').innerHTML=`<div class="card"><div class="kicker">READING REVIEW FINISHED</div><h2>阅读生词复习完成</h2><p class="muted">本轮 ${count} 题，答对 ${s.correct} 题，需巩固 ${s.wrong} 题。复习结果会单独记录，不影响688核心词学习进度。</p><button class="btn primary wide" onclick="navigate('reader')">返回阅读生词本</button><button class="btn wide" onclick="startReadReview('mixed')">重新综合复习</button></div>`;readReviewSession=null;refresh();return}
 const q=s.items[s.idx],label={word:'01 · 词义',original:'02 · 阅读原句',fresh:'03 · 新句迁移'}[q.mode],done=s.choice!==null;
 $('app').innerHTML=`<div class="card"><button class="btn smallbtn" onclick="navigate('reader')">← 阅读生词本</button><div class="review-kicker" style="margin-top:20px">${label} · ${s.idx+1} / ${s.items.length}</div><h2 style="margin-top:10px">${q.mode==='word'?'这个单词是什么意思？':'选出正确的句子翻译'}</h2><div class="read-quiz-prompt">${escapeWord(q.prompt)}</div><p class="review-sub">${q.mode==='fresh'?'这是另一句预先编写的英语例句。':'可以查看词性和语法；答题后显示解析。'}</p><button class="btn smallbtn" onclick="speak(readReviewSession.items[readReviewSession.idx].prompt)">♫ 朗读</button><div style="margin-top:13px">${q.opts.map((o,i)=>`<button class="btn option ${done&&o===q.correct?'selected':''}" ${done?'disabled':''} onclick="answerReadReview(${i})">${'ABCD'[i]}. ${escapeWord(o)}</button>`).join('')}</div>${done?`<div class="read-feedback"><b>${q.opts[s.choice]===q.correct?'✓ 答对了！':'再记一遍，下次还会复习。'}</b><p style="margin:9px 0">正确答案：${escapeWord(q.correct)}</p><p>${escapeWord(q.grammar)}</p></div><button class="btn primary wide" onclick="nextReadReview()">${s.idx===s.items.length-1?'查看成绩':'继续下一题 →'}</button>`:''}</div>`;
 refresh();
}
function answerReadReview(i){const s=readReviewSession;if(!s||s.choice!==null)return;const q=s.items[s.idx];s.choice=i;const ok=q.opts[i]===q.correct;const rec=readRecallRecord(q.word);rec.seen++;rec.last=day();if(ok){rec.correct++;rec.stage=Math.min(5,rec.stage+1);rec.due=later([1,2,4,7,15,30][rec.stage]);s.correct++}else{rec.wrong++;rec.stage=0;rec.due=later(1);s.wrong++}save();drawReadReview()}
function nextReadReview(){if(!readReviewSession)return;readReviewSession.idx++;readReviewSession.choice=null;drawReadReview()}

applyTheme();

if(data.lastVisit!==day()){data.lastVisit=day();save()}navigate('home');
